/* Generated voxel scenes, embedded for portable static hosting. */
const voxelScenes={"cast": "data:image/webp;base64,", "design": "data:image/webp;base64,", "cook": "data:image/webp;base64,", "travel": "data:image/webp;base64,"};
document.querySelectorAll("[data-scene]").forEach(img=>{const src=voxelScenes[img.dataset.scene];if(src)img.src=src;});
